{
  "technical_and_design_decisions": [
    "Each SPI (Mesos, Lattice, K8s, CF) will be extracted into its own independent Git repository with independent release cycles.",
    "A shared 'spring-cloud-deployer-spi-common' module will be created or updated to hold common interfaces, enums (including the new 'UNDEPLOYED' status), and base classes to ensure consistency across SPIs.",
    "Build system will remain Maven (consistent with Spring projects) with each repo publishing to Spring Milestone/Snapshot repositories.",
    "CI/CD pipelines will be replicated per repository using GitHub Actions, leveraging shared workflow templates.",
    "The 'UNDEPLOYED' status will be added as a new enum value in the common DeploymentState enum, distinct from UNKNOWN, representing a stream that exists but has never been deployed.",
    "Existing Mesos SPI work (U1) assumes code is already developed in a feature branch and only requires PR preparation, review, and merge.",
    "Repository extraction will follow the 'modulith' pattern: extract module, update package names if needed, add module-specific README and license headers."
  ],
  "assumptions": [
    "Current codebase is a single monorepo (likely 'spring-cloud-deployer-spi' or similar) containing all SPI implementations under one admin/project structure.",
    "Each SPI implementation (Mesos, Lattice, K8s, CF) is roughly equivalent in code size and complexity (~5-10 KLOC each).",
    "The team has write access to Spring GitHub organization and Maven publishing credentials.",
    "No major refactoring of SPI interfaces is required beyond adding the UNDEPLOYED status.",
    "Unit and integration test coverage exists and must be maintained; new tests needed for UNDEPLOYED status.",
    "Documentation updates include README per repo, CHANGELOG, and reference docs in spring-cloud-deployer main docs.",
    "U1 (Mesos SPI PR) represents ~2 weeks of prior development work already done; only PR overhead estimated.",
    "Dependency management: each SPI repo will depend on the common module via Maven coordinates.",
    "No breaking changes to public SPI APIs other than the additive UNDEPLOYED enum value."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Create Lattice SPI Repository",
      "activity_description": "Initialize new Git repository for Lattice SPI: set up Maven project structure, pom.xml with Spring Boot plugin, CI/CD workflows, CODEOWNERS, license headers. Extract Lattice SPI code from monorepo, adjust package names if needed, ensure tests pass. Publish initial snapshot.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2",
      "activity_name": "Create K8s SPI Repository",
      "activity_description": "Initialize new Git repository for Kubernetes SPI: same steps as Lattice. Extract K8s SPI code, update dependencies, validate with existing integration tests against a test cluster.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Create Mesos SPI Repository",
      "activity_description": "Initialize new Git repository for Mesos SPI: same steps. Note: existing work from U1 will be merged into this repo after PR approval.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Prepare and Submit PR for Existing Mesos SPI Work (U1)",
      "activity_description": "Review existing Mesos SPI feature branch, ensure code quality, write/update tests, update CHANGELOG, create PR against new Mesos SPI repo (or monorepo if repo not ready), address review feedback, merge.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Add UNDEPLOYED Status to Common SPI Module",
      "activity_description": "Modify shared DeploymentState enum in spring-cloud-deployer-spi-common to add UNDEPLOYED value. Update any base deployer logic that handles state transitions. Add unit tests for new enum. Release new version of common module.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement UNDEPLOYED Status in CF SPI",
      "activity_description": "Update CF SPI deployer to return UNDEPLOYED for streams/apps without deployment context. Modify CloudFoundryDeployer and related classes. Add integration tests simulating undeployed stream. Update CF SPI documentation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement UNDEPLOYED Status in Lattice SPI",
      "activity_description": "Update Lattice SPI deployer (in new repo) to support UNDEPLOYED status. Add tests. Since repo is new, this can be part of initial release.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement UNDEPLOYED Status in K8s SPI",
      "activity_description": "Update Kubernetes SPI deployer (in new repo) to support UNDEPLOYED status. Handle Kubernetes-specific deployment context. Add tests.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement UNDEPLOYED Status in Mesos SPI",
      "activity_description": "Update Mesos SPI deployer (in new repo) to support UNDEPLOYED status. Coordinate with U1 PR merge. Add tests.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "Cross-SPI Consistency Validation and Documentation",
      "activity_description": "Verify UNDEPLOYED behavior is consistent across all four SPIs: write cross-SPI integration test suite (or extend existing), update reference documentation, create migration guide for users upgrading from UNKNOWN to UNDEPLOYED semantics. Coordinate version bumps and release notes.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Update Monorepo Build and Release Scripts",
      "activity_description": "Remove extracted SPI modules from monorepo build. Update parent pom, release profiles, and documentation to point to new repositories. Ensure no broken links in main Spring Cloud Deployer docs.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 30
  }
}

